/** The box. Colors, the tick and the hit area live in `checkbox.css`. */
export const checkboxClass =
	"rx-check relative size-4 shrink-0 cursor-pointer appearance-none rounded-(--radius-check) border focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed";

/** The label that wraps the box, so the whole row is clickable. */
export const checkboxLabelClass =
	"inline-flex cursor-pointer items-center gap-2 text-[13px]/5 tracking-[-0.15px] text-foreground has-disabled:cursor-not-allowed has-disabled:text-(--disabled-foreground)";

"use client";

import { type InputHTMLAttributes, type Ref, useEffect, useRef } from "react";
import { checkboxClass, checkboxLabelClass } from "./checkbox.styles";
import { cn } from "@/lib/utils";

export type CheckboxProps = Omit<InputHTMLAttributes<HTMLInputElement>, "type" | "size"> & {
	/** The partly-checked look, such as a "select all" with some children chosen. */
	mixed?: boolean;
	ref?: Ref<HTMLInputElement>;
};

/**
 * A native checkbox. With children it renders a `<label>` around the box, so the text is the
 * accessible name and the whole row is clickable. Without children, give it an `aria-label`.
 * `mixed` is derived state: the browser clears it when the user clicks, so set it again from your
 * own state.
 */
export function Checkbox({ mixed, className, children, ref, ...rest }: CheckboxProps) {
	const inner = useRef<HTMLInputElement>(null);

	useEffect(() => {
		if (inner.current) inner.current.indeterminate = !!mixed;
	}, [mixed]);

	const input = (
		<input
			{...rest}
			type="checkbox"
			ref={(node) => {
				inner.current = node;
				if (typeof ref === "function") ref(node);
				else if (ref) ref.current = node;
			}}
			className={children ? checkboxClass : cn(checkboxClass, className)}
		/>
	);

	if (!children) return input;
	return (
		<label className={cn(checkboxLabelClass, className)}>
			{input}
			{children}
		</label>
	);
}
